              }}
            >
              {t('sendSteer')}
            </button>
            <button
              className={`qm-btn ${queueMode === 'followUp' ? 'active' : ''}`}
              onClick={(e) => {
                e.stopPropagation();
                setQueueMode('followUp');
              }}
            >
              {t('sendFollowUp')}
            </button>
          </div>
        )}

        <span style={{ flex: 1 }} />

        {/* live stream counter: ↓tokens · t/s (pi-web style) */}
        {streaming && (() => {
          const run = conv.runStats;
          const estTokens = Math.round(run.outputChars / 3.5);
