import { t } from '../i18n';

interface SkillItem {
  name: string;
  description: string;
  filePath: string;
  source?: string;
  scope?: string;
}

interface PromptItem {
  name: string;
  description?: string;
  filePath: string;
}

export default function SkillsPanel({ cwd: initialCwd }: { cwd: string }) {
  const [cwd, setCwd] = useState(initialCwd);
