        >
          <input className="panel-search mono" value={cwdDraft} onChange={(e) => setCwdDraft(e.target.value)} />
        </form>
        <button className="btn btn-sm" onClick={() => setAddingSkill((v) => !v)}>＋ {t('addSkill')}</button>
